def compute(vars):
    furniture_equipment = vars["v1"]
    total_assets_at_cost = vars["v2"]
    if total_assets_at_cost == 0:
        return None
    percentage = furniture_equipment / total_assets_at_cost * 100
    return {
        "value": percentage,
        "trace": {
            "furniture_equipment": furniture_equipment,
            "total_assets_at_cost": total_assets_at_cost,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
